(()=>{'use strict';
const species={HQ:'C₆H₄(OH)₂(aq)',Q:'C₆H₄O₂(aq)',peroxide:'H₂O₂(aq)',water:'H₂O(l)',hydrogen:'H₂(g)',oxygen:'O₂(g)',carbon:'C(s, graphite)',co2:'CO₂(g)',methane:'CH₄(g)',ethene:'C₂H₄(g)',ethane:'C₂H₆(g)',ethyne:'C₂H₂(g)',methanol:'CH₃OH(l)'};
// First problem: supplied exercise. Other rounded data: OpenStax Appendix G.
const bank=[
{title:'Bombardier beetle spray',source:'Values from your supplied practice question.',target:{HQ:-1,peroxide:-1,Q:1,water:2},reactions:[{v:{HQ:-1,Q:1,hydrogen:1},h:177},{v:{water:-2,oxygen:-1,peroxide:2},h:189.2},{v:{water:-1,hydrogen:1,oxygen:.5},h:285.5}],solution:[1,-.5,-1]},
{title:'Formation of methane',target:{carbon:-1,hydrogen:-2,methane:1},reactions:[{v:{carbon:-1,oxygen:-1,co2:1},h:-393.5},{v:{hydrogen:-1,oxygen:-.5,water:1},h:-285.8},{v:{methane:-1,oxygen:-2,co2:1,water:2},h:-890.5}],solution:[1,2,-1]},
{title:'Hydrogenation of ethene',target:{ethene:-1,hydrogen:-1,ethane:1},reactions:[{v:{ethene:-1,oxygen:-3,co2:2,water:2},h:-1411.0},{v:{hydrogen:-1,oxygen:-.5,water:1},h:-285.8},{v:{ethane:-1,oxygen:-3.5,co2:2,water:3},h:-1560.4}],solution:[1,1,-1]},
{title:'Hydrogenation of ethyne',target:{ethyne:-1,hydrogen:-2,ethane:1},reactions:[{v:{ethyne:-1,oxygen:-2.5,co2:2,water:1},h:-1300.2},{v:{hydrogen:-1,oxygen:-.5,water:1},h:-285.8},{v:{ethane:-1,oxygen:-3.5,co2:2,water:3},h:-1560.4}],solution:[1,2,-1]},
{title:'Formation of liquid methanol',target:{carbon:-1,hydrogen:-2,oxygen:-.5,methanol:1},reactions:[{v:{carbon:-1,oxygen:-1,co2:1},h:-393.5},{v:{hydrogen:-1,oxygen:-.5,water:1},h:-285.8},{v:{methanol:-1,oxygen:-1.5,co2:1,water:2},h:-725.9}],solution:[1,2,-1]}
];
const clean=x=>Math.abs(x)<1e-8?0:x,scale=(v,k)=>Object.fromEntries(Object.entries(v).map(([s,n])=>[s,n*k]));
function combine(reactions,factors){const left={},right={},net={};let h=0;reactions.forEach((r,i)=>{h+=r.h*factors[i];Object.entries(r.v).forEach(([s,n])=>{const q=n*factors[i],side=q<0?left:right;side[s]=(side[s]||0)+Math.abs(q);net[s]=clean((net[s]||0)+q);});});const cancelled={};Object.keys(net).forEach(s=>{cancelled[s]=Math.min(left[s]||0,right[s]||0)});return{left,right,net,cancelled,h:clean(h)};}
function matches(a,b){return [...new Set([...Object.keys(a),...Object.keys(b)])].every(s=>Math.abs((a[s]||0)-(b[s]||0))<1e-7);}
function amount(n){if(Math.abs(n-Math.round(n))<1e-8)return String(Math.round(n));for(let d=2;d<=64;d++)if(Math.abs(n*d-Math.round(n*d))<1e-8)return Math.round(n*d)+'/'+d;return Number(n.toFixed(5)).toString();}
function fmt(n){return (n<0?'−':'+')+Math.abs(n).toLocaleString('en-GB',{maximumFractionDigits:4,minimumFractionDigits:1,useGrouping:false});}
function term(s,n){return (Math.abs(n-1)<1e-8?'':amount(n)+' ')+species[s];}
function equation(v){return [-1,1].map(sign=>Object.entries(v).filter(([,n])=>n*sign>1e-8).map(([s,n])=>term(s,Math.abs(n))).join(' + ')||'∅').join(' → ');}
function colouredEquation(v,target={},net={}){return [-1,1].map(sign=>Object.entries(v).filter(([,q])=>q*sign>1e-8).map(([s,q])=>{const match=(target[s]||0)*sign>0&&Math.abs((net[s]||0)-target[s])<1e-7;const side=sign<0?'reactant':'product';return `<span class="hp-species hp-${side}${match?' hp-matched':''}" title="${match?'Combined net amount matches the target':sign<0?'Reactant':'Product'}">${term(s,Math.abs(q))}${match?'<span class="hp-tick" aria-label="Matches target">✓</span>':''}</span>`;}).join(' <span class="hp-plus">+</span> ')||'∅').join(' <span class="hp-arrow">→</span> ');}
function problem(index,variant=false,rng=Math.random){const base=bank[index],reactions=base.reactions.map((r,i)=>{const k=variant?([.5,1,2][Math.floor(rng()*3)]*(rng()<.5?-1:1)):1;return{v:scale(r.v,k),h:r.h*k,solution:base.solution[i]/k}});if(variant)for(let i=2;i>0;i--){const j=Math.floor(rng()*(i+1));[reactions[i],reactions[j]]=[reactions[j],reactions[i]];}return{...base,reactions};}
if(typeof module!=='undefined'&&module.exports)module.exports={species,bank,combine,matches,amount,equation,problem,colouredEquation};if(typeof document==='undefined')return;
const $=id=>document.getElementById('hess-'+id);if(!$('game'))return;let index=Math.floor(Math.random()*bank.length),current=problem(index,true),factors=[1,1,1],combined=null;
function clearResult(){combined=null;$('combined').hidden=true;$('feedback').textContent='';$('answer').value='';$('answer').removeAttribute('aria-invalid');}
function row(i){const r=current.reactions[i],f=factors[i];$('original-'+i).innerHTML='Given: '+colouredEquation(r.v)+'   ΔH° = '+fmt(r.h)+' kJ';$('eq-'+i).innerHTML=colouredEquation(scale(r.v,f),current.target,combine(current.reactions,factors).net);$('enthalpy-'+i).textContent='ΔH° = '+fmt(r.h*f)+' kJ';$('factor-'+i).textContent='Overall factor: '+(f<0?'−':'')+amount(Math.abs(f));$('flip-'+i).setAttribute('aria-pressed',String(f<0));}
function refreshEquations(){const net=combine(current.reactions,factors).net;$('target').innerHTML=colouredEquation(current.target,current.target,net);for(let i=0;i<3;i++)row(i);}
function load(){factors=[1,1,1];clearResult();$('title').textContent=current.title;$('source').innerHTML=current.source||'Rounded practice data derived from <a href="https://openstax.org/books/chemistry-2e/pages/g-standard-thermodynamic-properties-for-selected-substances" target="_blank" rel="noopener">OpenStax thermodynamic data</a>.';refreshEquations();for(let i=0;i<3;i++)$('operand-'+i).value=2;}
for(let i=0;i<3;i++)for(const operation of ['multiply','divide','flip','reset'])$(operation+'-'+i).addEventListener('click',()=>{const operand=Number($('operand-'+i).value);if(['multiply','divide'].includes(operation)&&(!Number.isFinite(operand)||operand<=0||operand>10)){$('feedback').textContent='Use a positive multiplier or divisor no greater than 10.';return;}const next=operation==='reset'?1:operation==='flip'?-factors[i]:factors[i]*(operation==='multiply'?operand:1/operand);if(Math.abs(next)<1/64||Math.abs(next)>64){$('feedback').textContent='Keep the overall factor between 1/64 and 64 in magnitude.';return;}factors[i]=next;clearResult();refreshEquations();});
function cancellationSide(totals,cancelled){return Object.entries(totals).filter(([,n])=>n>1e-8).map(([s,n])=>{const c=cancelled[s]||0,remaining=clean(n-c);return [c>1e-8?`<span class="hp-cancel" title="Cancels on both sides">${term(s,c)}</span>`:'',remaining>1e-8?`<span>${term(s,remaining)}</span>`:''].filter(Boolean).join(' + ')}).join(' + ')||'∅';}
$('combine').addEventListener('click',()=>{combined=combine(current.reactions,factors);$('combined').hidden=false;$('feedback').textContent='';$('answer').value='';$('answer').removeAttribute('aria-invalid');$('sum-rows').innerHTML=current.reactions.map((r,i)=>`<div><span>${colouredEquation(scale(r.v,factors[i]),current.target,combined.net)}</span><strong>${fmt(r.h*factors[i])} kJ</strong></div>`).join('');$('cancellation').innerHTML=cancellationSide(combined.left,combined.cancelled)+' <span class="hp-arrow">→</span> '+cancellationSide(combined.right,combined.cancelled);const cancelled=Object.entries(combined.cancelled).filter(([,n])=>n>1e-8);$('cancel-list').textContent=cancelled.length?'Cancelled from each side: '+cancelled.map(([s,n])=>term(s,n)).join(', ')+'.':'No substances cancel yet.';$('net').innerHTML=colouredEquation(combined.net,current.target,combined.net);$('sum').textContent='ΔH° = '+current.reactions.map((r,i)=>'('+fmt(r.h*factors[i])+')').join(' + ')+' kJ';const match=matches(combined.net,current.target);$('match').textContent=match?'The net equation matches the target.':'The net equation does not match the target yet.';$('match').dataset.correct=String(match);$('check').disabled=!match;$('answer').disabled=!match;$('combined').classList.remove('hp-animate');void $('combined').offsetWidth;$('combined').classList.add('hp-animate');});
$('check').addEventListener('click',()=>{if(!combined||!matches(combined.net,current.target))return;const raw=$('answer').value.trim(),answer=Number(raw);if(!raw||!Number.isFinite(answer)){$('feedback').textContent='Enter an enthalpy value, including its sign.';$('answer').setAttribute('aria-invalid','true');return;}const correct=Math.abs(answer-combined.h)<=.05+1e-9;$('answer').setAttribute('aria-invalid',String(!correct));$('feedback').textContent=correct?'Correct. ΔH° = '+fmt(combined.h)+' kJ for the target reaction as written.':'Check the signs and add the three adjusted enthalpy values. Give your answer to one decimal place.';});
$('answer').addEventListener('keydown',e=>{if(e.key==='Enter'&&!$('check').disabled)$('check').click()});$('restart').addEventListener('click',load);$('next').addEventListener('click',()=>{index=(index+1+Math.floor(Math.random()*(bank.length-1)))%bank.length;current=problem(index,true);load()});load();
})();
